(()=>{'use strict';const reduced=matchMedia('(prefers-reduced-motion: reduce)');let started=false,observer=null,context=null,progress=null,scheduled=false,listeners=null;const load=()=>new Promise(resolve=>{if(window.gsap){resolve(window.gsap);return;}const script=document.createElement('script');script.src='vendor/gsap.min.js';script.onload=()=>resolve(window.gsap);script.onerror=()=>resolve(null);document.head.append(script);});
async function start(){if(started||reduced.matches)return;started=true;const gsap=await load();if(!gsap||reduced.matches){started=false;return;}listeners=new AbortController();context=gsap.context(()=>{observer=new IntersectionObserver(entries=>{for(const entry of entries)if(entry.isIntersecting){gsap.fromTo(entry.target,{y:22},{y:0,duration:.7,ease:'power2.out',clearProps:'transform'});observer.unobserve(entry.target);}},{threshold:.12});document.querySelectorAll('.project-exhibit,.project-pair>article,.research-layout,.course-list,.about-layout').forEach(el=>observer.observe(el));document.querySelectorAll('[data-project]').forEach(button=>button.addEventListener('click',()=>{if(!reduced.matches)gsap.fromTo('.field-caption',{y:6,opacity:.7},{y:0,opacity:1,duration:.28,clearProps:'all'});},{signal:listeners.signal}));});progress=document.createElement('div');progress.className='phase-progress';progress.setAttribute('aria-hidden','true');document.body.append(progress);update();}
function update(){scheduled=false;if(progress){const span=document.documentElement.scrollHeight-innerHeight;progress.style.transform='scaleX('+Math.max(0,Math.min(1,span?scrollY/span:0))+')';}}addEventListener('scroll',()=>{if(!scheduled&&!reduced.matches){scheduled=true;requestAnimationFrame(update);}},{passive:true});function stop(){listeners?.abort();observer?.disconnect();context?.revert();progress?.remove();progress=null;started=false;}reduced.addEventListener('change',()=>reduced.matches?stop():start());if('requestIdleCallback'in window)requestIdleCallback(start,{timeout:1500});else setTimeout(start,300);
})();
